inline const Blob* Find(const char* file, const char* entry, const char* profile, unsigned long long hash) {
    char key[160];
    snprintf(key, sizeof(key), "%s:%s:%s", file, entry, profile);
    for (auto& b : kBlobs)
        if (b.data && b.hash == hash && !strcmp(b.key, key)) return &b;
    return nullptr;
}
